package com.agenda.clinica.exception;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.dao.DataIntegrityViolationException; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(ReglaNegocioException.class) ResponseEntity<?> regla(ReglaNegocioException e){return ResponseEntity.status(409).body(Map.of("mensaje",e.getMessage()));} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> noExiste(Exception e){return ResponseEntity.status(404).body(Map.of("mensaje","El registro solicitado no existe."));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validacion(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("mensaje","Revisa los campos ingresados.","errores",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList()));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> integridad(Exception e){return ResponseEntity.status(409).body(Map.of("mensaje","No se puede completar la operación porque el registro está relacionado o duplicado."));} }
